// Copied outside the checkout by test-extension-asar. Application imports must
// resolve inside its archive; only Electron and Node built-ins come from outside.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),Module=require('node:module');
const {app,BrowserWindow,WebContentsView,ipcMain,session,protocol,utilityProcess,safeStorage}=require('electron');
const config=JSON.parse(fs.readFileSync(process.argv.at(-1))),resolved=new Set(),checks=[],preloads=[],preloadErrors=[];
const failStartup=error=>{fs.writeFileSync(path.join(config.directory,'failure.json'),JSON.stringify({error:error.stack||String(error),checks,preloads,preloadErrors},null,2));console.error(error);app.exit(1);};process.on('uncaughtException',failStartup);process.on('unhandledRejection',failStartup);
const originalResolve=Module._resolveFilename;Module._resolveFilename=function(name,...args){const value=originalResolve.call(this,name,...args);if(name!=='electron'&&!Module.isBuiltin(name)){assert.ok(value.startsWith(config.archive+path.sep),'Unexpected external application dependency: '+value);resolved.add(value);}return value;};
app.setPath('userData',path.join(config.directory,'user-data'));const {VIEW_SCHEME}=require(config.archive+'/electron/plugins/extensionViewProtocol.cjs');protocol.registerSchemesAsPrivileged([VIEW_SCHEME]);
let host,views,owner;
const until=async fn=>{for(const end=Date.now()+10000;Date.now()<end;){const result=await fn();if(result)return result;await new Promise(resolve=>setTimeout(resolve,20));}throw Error('Archived view readiness deadline');};
app.whenReady().then(async()=>{
 const archivedRequire=Module.createRequire(config.archive+'/package.json');assert.ok(archivedRequire.resolve('tar').startsWith(config.archive+path.sep));for(const name of ['typescript','esbuild','vite','react'])assert.throws(()=>archivedRequire.resolve(name),{code:'MODULE_NOT_FOUND'});checks.push('archive supplies its tar dependency closure without checkout or development dependencies');
 const {PluginManager}=require(config.archive+'/electron/plugins/manager.cjs'),{ExtensionRuntime}=require(config.archive+'/electron/plugins/extensionRuntime.cjs'),{ExtensionViews}=require(config.archive+'/electron/plugins/extensionViews.cjs');require(config.archive+'/electron/plugins/ipcGuard.cjs').installExtensionViewIpcGuard(ipcMain);
 const manager=new PluginManager(path.join(config.directory,'plugins'),'2.0.0'),[row]=await manager.install(config.source,true);let worker;
 host=new ExtensionRuntime({manager,safeStorage,utilityProcess:{fork(file,...args){worker=file;return utilityProcess.fork(file,...args);}}});
 owner=new BrowserWindow({show:false,webPreferences:{sandbox:true,nodeIntegration:false,contextIsolation:true,backgroundThrottling:false}});await owner.loadURL('data:text/html,<!doctype html><title>ASAR owner</title>');
 views=new ExtensionViews({runtime:host,manager,ipcMain,session,getWindow:()=>owner,WebContentsView:function(options){preloads.push(options.webPreferences.preload);const view=new WebContentsView(options);view.webContents.on('preload-error',(_event,file,error)=>preloadErrors.push({file,error:String(error)}));return view;}});host.views=views;host.onStopped=job=>views.stopped(job);
 await assert.rejects(host.start(row.key),/trust/);assert.equal(worker,undefined);checks.push('trust refusal precedes utility process launch');
 await host.trust(row.key);await host.start(row.key);assert.ok(worker.startsWith(config.archive+path.sep));assert.deepEqual(await host.execute('studio.asar.hello',{value:42}),{input:{value:42},node:'function',saved:{value:42}});checks.push('archived utility worker activates and round-trips host settings');
 if(config.missingPreload){
  await assert.rejects(views.open('studio.asar.panel'),/did not start|preload/i);await until(()=>preloadErrors.length);assert.ok(preloadErrors.every(value=>value.file.startsWith(config.archive+path.sep)));assert.equal(views.active.size,0);await views.sessions.settle();assert.equal(views.sessions.snapshot().leased,0);checks.push('missing archived preload refuses the native view and releases its session');
 }else{
  await views.open('studio.asar.panel');const job=views.active.get('studio.asar.panel');views.layout(job.id,{x:10,y:60,width:400,height:240,visible:true});
  await until(()=>job.view.webContents.executeJavaScript(`document.querySelector('#result').textContent==='{"kind":"reply","value":42}'`));
  const state=await job.view.webContents.executeJavaScript(`({info:window.fixtureInfo,error:window.fixtureError||null,require:typeof require,process:typeof process,api:typeof window.api,color:getComputedStyle(document.querySelector('#result')).color})`);assert.equal(state.info.id,'studio.asar.panel');assert.equal(state.error,null);assert.equal(state.require,'undefined');assert.equal(state.process,'undefined');assert.equal(state.api,'undefined');assert.equal(state.color,'rgb(24, 145, 83)');assert.notEqual(job.view.webContents.getOSProcessId(),owner.webContents.getOSProcessId());assert.equal(job.view.webContents.getLastWebPreferences().sandbox,true);assert.ok(preloads.every(file=>file===config.archive+'/electron/plugins/extensionViewPreload.cjs'));assert.deepEqual(preloadErrors,[]);checks.push('archived sandbox preload, protocol HTML/JS/CSS and two-way worker/view messages work in a separate renderer');
  assert.equal(await job.view.webContents.executeJavaScript(`fetch('./plugin.json').then(()=>false,()=>true)`),true);checks.push('native archived view refuses undeclared resources');
  await host.stop(row.key);await views.sessions.settle();assert.equal(views.active.size,0);assert.equal(views.senders.size,0);assert.equal(views.sessions.snapshot().leased,0);assert.equal(host.active.size,0);assert.equal(host.commands.size,0);checks.push('Stop releases the native view, private session and utility registrations');
  await host.start(row.key);assert.deepEqual(await host.call(host.active.get(row.key),'configuration.get','saved'),{value:42});await views.open('studio.asar.panel');await until(()=>views.active.get('studio.asar.panel').view.webContents.executeJavaScript(`document.querySelector('#result').textContent==='{"kind":"reply","value":42}'`));checks.push('restart preserves settings and reopens the archived bridge');
 }
 await host.dispose();views.dispose();await views.sessions.settle();assert.equal(views.active.size,0);assert.equal(host.active.size,0);assert.equal(views.sessions.snapshot().leased,0);owner.destroy();
 fs.writeFileSync(path.join(config.directory,'result.json'),JSON.stringify({ok:true,missingPreload:config.missingPreload,checks,worker,preloads,preloadErrors,resolvedModules:[...resolved].sort(),sessions:views.sessions.snapshot(),userData:app.getPath('userData'),nodePath:process.env.NODE_PATH||null,noSandbox:process.argv.includes('--no-sandbox'),environment:{electron:process.versions.electron,node:process.version,platform:process.platform,arch:process.arch}},null,2));app.exit(0);
}).catch(async error=>{try{await host?.dispose();views?.dispose();await views?.sessions.settle();owner?.destroy();}catch{}fs.writeFileSync(path.join(config.directory,'failure.json'),JSON.stringify({error:error.stack,checks,preloads,preloadErrors},null,2));console.error(error);app.exit(1);});
